days = [
    # Day 1 -- 50 records
    '',
    # Day 2 -- 70 records
    '',
    # Day 3 -- 230 records
    '',
    # Day 4 -- 284 records
    '',
    # Day 5 -- 235 records
    '',
    # Day 6 -- 245 records
    '',
    # Day 7 -- 255 records
    '',
    # Day 8 -- 225 records
    '',
    # Day 9 -- 137 records
    '',
    # Day 10 -- 70 records
    '',
]

# Test Cases: 
# For a tie: days = ['AUSJEKWAGKWIEDJAKWIEWAKSJDJD]
# 
causes = []
counts = []

for day in days:
    for string_i in range(6, len(day), 7):
        index = -1
        if day[string_i] in causes:
            index = causes.index(day[string_i])
        else:
            causes.append(day[string_i])
            counts.append(0)
        counts[index] += 1
print(causes)
print(counts)

for i in range(1, len(counts)):
    current = counts[i]
    name = causes[i]
    j = i-1

    while j >= 0 and current > counts[j]:
        temp = causes[j+1]
        causes[j+1] = causes[j]
        causes[j] = temp
        
        temp = counts[j+1]
        counts[j+1] = counts[j]
        counts[j] = temp
                
        j -= 1

    causes[j+1] = name
    counts[j+1] = current

total = sum(counts)
print(f"Total records processed: {total}")

print("Disruption ranking (most to least frequent):")
num = 1; printed = [0 for _ in range(8)]
for cause in causes:
    match cause:
        case "W": print(f"{num}. Weather ", end = ""); printed[0] = 1
        case "C": print(f"{num}. Crew Timeout ", end = ""); printed[1] = 1
        case "M": print(f"{num}. Mechanical ", end = ""); printed[2] = 1
        case "G": print(f"{num}. Ground Stop ", end = ""); printed[3] = 1
        case "D": print(f"{num}. Deicing ", end = ""); printed[4] = 1
        case "P": print(f"{num}. Gate Conflict ", end = ""); printed[5] = 1
        case "B": print(f"{num}. Connecting-Flight Backup ", end = ""); printed[6] = 1
        case "S": print(f"{num}. Software/Scheduling System ", end = ""); printed[7] = 1
    print(f"({cause}): {counts[num-1]}")
    num += 1

weather_types = ["Weather (W)", "Crew Timeout (C)", "Mechanical (M)", "Ground Stop (G)", "Deicing (D)", "Gate Conflict (P)", 
                "Connecting-Flight Backup (B)", "Software/Scheduling System (S)"]
for i in range(8):
    if printed[i] == 0:
        print(f"{index}. {weather_types[i]}: 0")
        index += 1
    
